    public static final Set<String> TOOLS=Set.of("inspect_state_push_targets","inspect_event_handlers","inspect_score_events","subscribe_score_events","inspect_object_events","subscribe_object_events","subscribe_ui_feedback","subscribe_events","subscribe_shared_state","inspect_subscription","set_subscription_state");
