        if(tool.equals("inspect_state_push_targets")){keys(n,Set.of("instance_id","offset"),Set.of("instance_id"));int offset=integer(n,"offset",0);if(offset<0||offset>128)throw new IllegalArgumentException();return new EventToolRequest(tool,null,UUID.fromString(text(n,"instance_id","")),0,"",offset);}
        if(tool.equals("inspect_event_handlers")){keys(n,Set.of("instance_id","offset"),Set.of("instance_id"));int offset=integer(n,"offset",0);if(offset<0||offset>128)throw new IllegalArgumentException();return new EventToolRequest(tool,null,UUID.fromString(text(n,"instance_id","")),0,"",offset);}
        if(tool.equals("inspect_score_events")){keys(n,Set.of("objective","offset"),Set.of());String objective=text(n,"objective","");if(!objective.isEmpty())ScoreEventFilter.name(objective,16);int offset=integer(n,"offset",0);if(offset<0||offset>(objective.isEmpty()?16384:4096))throw new IllegalArgumentException();return new EventToolRequest(tool,null,null,0,"",offset,objective);}
        if(tool.equals("subscribe_score_events")){
            var fields=new HashSet<>(ScoreEventFilter.FIELDS);fields.addAll(Set.of("mode","goal","max_wakes","max_model_calls","pending_limit","cooldown_ms","ttl_seconds","script","push"));keys(n,fields,Set.of("objective","criteria","mode"));
            var filter=ScoreEventFilter.parse(n);String mode=text(n,"mode","");if(mode.equals("AGENT_WAKE")&&(!n.has("goal")||!n.has("max_wakes")||!n.has("max_model_calls")))throw new IllegalArgumentException();
            var request=new RuntimeEventStore.Request(Set.of(ScoreEventFilter.SOURCE),mode,null,text(n,"goal",""),integer(n,"max_wakes",0),integer(n,"max_model_calls",0),integer(n,"pending_limit",4),integer(n,"cooldown_ms",1000),integer(n,"ttl_seconds",3600),null,null,null,filter,ScriptEventConsumer.optional(n),StatePushConsumer.optional(n));return new EventToolRequest(tool,request,null,0,"",0);
        }
