        if(tool.equals("subscribe_object_events")){
            var fields=new HashSet<>(ObjectInteractionFilter.FIELDS);fields.addAll(Set.of("mode","goal","max_wakes","max_model_calls","pending_limit","cooldown_ms","ttl_seconds","script","push"));var required=new HashSet<>(ObjectInteractionFilter.FIELDS);required.remove("actor_ids");required.add("mode");keys(n,fields,required);
            var filter=ObjectInteractionFilter.parse(n);String mode=text(n,"mode","");if(mode.equals("AGENT_WAKE")&&(!n.has("goal")||!n.has("max_wakes")||!n.has("max_model_calls")))throw new IllegalArgumentException();
            var request=new RuntimeEventStore.Request(Set.of(ObjectInteractionFilter.SOURCE),mode,null,text(n,"goal",""),integer(n,"max_wakes",0),integer(n,"max_model_calls",0),integer(n,"pending_limit",4),integer(n,"cooldown_ms",1000),integer(n,"ttl_seconds",3600),null,null,filter,null,ScriptEventConsumer.optional(n),StatePushConsumer.optional(n));return new EventToolRequest(tool,request,null,0,"",0);
        }
