            var filter=dev.mineagent.runtime.core.feedback.FeedbackSubscriptionFilter.parse(n);String mode=text(n,"mode","");if(mode.equals("AGENT_WAKE")&&(!n.has("goal")||!n.has("max_wakes")||!n.has("max_model_calls")))throw new IllegalArgumentException();
            return new EventToolRequest(tool,new RuntimeEventStore.Request(Set.of("UI_FEEDBACK"),mode,null,text(n,"goal",""),integer(n,"max_wakes",0),integer(n,"max_model_calls",0),integer(n,"pending_limit",4),integer(n,"cooldown_ms",1000),integer(n,"ttl_seconds",3600),null,filter),null,0,"",0);
