            var filter=dev.mineagent.runtime.core.shared.SharedSubscriptionFilter.parse(n);String mode=text(n,"mode","");if(mode.equals("AGENT_WAKE")&&(!n.has("max_wakes")||!n.has("max_model_calls")||!n.has("goal")))throw new IllegalArgumentException();
            var request=new RuntimeEventStore.Request(Set.of("SHARED_STATE_CHANGED"),mode,null,text(n,"goal",""),integer(n,"max_wakes",0),integer(n,"max_model_calls",0),integer(n,"pending_limit",4),integer(n,"cooldown_ms",1000),integer(n,"ttl_seconds",3600),filter,null,null,null,ScriptEventConsumer.optional(n),StatePushConsumer.optional(n));return new EventToolRequest(tool,request,null,0,"",0);
